<script setup lang="ts">import type { NuxtError } from '#app'; const props = defineProps<{ error: NuxtError }>(); const message = computed(() => props.error.statusCode === 404 ? 'The page you requested could not be found.' : 'The application could not complete this request.')</script>
<template><NuxtLayout><div class="page-shell"><ErrorState :title="error.statusCode === 404 ? 'Page not found' : 'Something went wrong'" :message="message"><template #action><BaseButton @click="clearError({ redirect: '/dashboard' })">Return to dashboard</BaseButton></template></ErrorState></div></NuxtLayout></template>
